function setup() {
  const world = new World([], [], 33);
  world.player = createTank(
    world.nextId(),
    { ...STARTER, parts: [...STARTER.parts, { ...STARTER.parts[1], type: 5005, key: 'field' }] },
    'player',
    0,
    0,
    50,
    20,
